"""Real aggregate UI, CSV, focus, context and restriction workflows."""
from qa_support import *
mode='aggregate'if '--aggregate'in sys.argv else'internal';q=QA('comparison_ui_'+mode,profile=mode);q.result['examples']=[]
def click(s):q.ev('document.querySelector('+json.dumps(s)+').click();true',userGesture=True)
def open_reading(n):q.question(n);click('#w28OpenComparison');q.wait('!!W28Census.state?.model')
def back():click('#w28Back');q.wait("document.querySelector('#questionDialog').open");q.close_dialog()
def work():
 q.c.call('Emulation.setDeviceMetricsOverride',{'width':1366,'height':1000,'deviceScaleFactor':1,'mobile':False});q.go();q.check(q.ev("performance.getEntriesByType('resource').filter(r=>r.name.includes('/api/census-comparison/')).length")==0,'Cover requests no comparative school context or aggregate');q.check(q.ev('(window.W25OperationalModel?.cachedUFs??0)')==0,'Cover preserves zero operational UF partitions');q.ev("location.hash='#diagnostico';true");q.wait('!!W15App.lastData');before=q.ev('JSON.stringify(W15App.lastData)');open_reading('28');m=q.ev('W28Census.state.model');q.check(m['base']['common']==39209 and m['base']['eligible']==53555,'Selo real common cohort is 39209 of 53555');q.check(m['base']['flags']['common_without_usable_coordinates']==7765,'Selo includes 7765 paired schools without usable coordinates');q.check(q.ev("document.querySelector('#w28ActiveContent').innerText.includes('Parcial/complementar')&&document.querySelector('#w28ActiveContent').innerText.includes('não intercambiáveis')"),'Complementary status and no false agreement are visible');q.check(q.ev("document.querySelectorAll('#w28ActiveContent .w28-source').length")==2,'Two distinctly titled sources have visible references');q.check(q.ev('JSON.stringify(W15App.lastData)')==before,'Original diagnostic data and percentages remain untouched')
 q.c.call('Input.dispatchKeyEvent',{'type':'keyDown','key':'Escape','code':'Escape','windowsVirtualKeyCode':27});q.c.call('Input.dispatchKeyEvent',{'type':'keyUp','key':'Escape','code':'Escape','windowsVirtualKeyCode':27});q.wait("document.querySelector('#questionDialog').open");q.check(q.ev("document.activeElement.id==='w28OpenComparison'"),'Escape restores detail and focus to the complementary action');q.close_dialog()
 for uf,ibge in [('PA','1506807'),('PI','2211001'),('BA','2903508')]:
  q.select({'uf':uf,'ibge':ibge});snapshot=q.ev('W15.summary()')
  for n in ['22','28','58','81','94','98']:
   open_reading(n);m=q.ev('W28Census.state.model');b=m['base'];q.check(b['common']+sum(r['schools']for r in b['losses'])==b['eligible'],'Q'+n+' '+ibge+' exclusive losses reconcile');q.check(all(o['denominator']==b['common']for k in['wash','census']for o in m[k]['options']),'Q'+n+' '+ibge+' both distributions use the same observed schools');q.check(q.ev('W15.summary()')==snapshot,'Q'+n+' '+ibge+' preserves coverage and participation');q.result['examples'].append(m);back()
 # Actual CSV download, restricted to the active allowed aggregate.
 q.select({'uf':'PA','ibge':'1506807'});open_reading('28');download=q.runtime/'downloads';download.mkdir();q.c.call('Browser.setDownloadBehavior',{'behavior':'allow','downloadPath':str(download)});click('#w28CSV');q.wait("document.querySelector('#w28DownloadStatus').innerText.includes('baixado')");end=time.monotonic()+10
 while time.monotonic()<end and not list(download.glob('*.csv')):time.sleep(.1)
 files=list(download.glob('*.csv'));q.check(len(files)==1,'Browser downloads exactly the selected comparative CSV');text=files[0].read_text(encoding='utf-8-sig');q.check('2026-10-26'in text and'2025'in text and'w28_20261030_v1'in text,'CSV preserves source years, release and contract');q.check(all(t not in text.splitlines()[0].casefold()for t in ['inep','nome_escola','latitude','longitude']),'CSV has no school identity or coordinate columns');q.result['csv']={'bytes':files[0].stat().st_size,'sha256':sha(files[0]),'path':str(files[0])};back()
 # Actual backdrop click returns to the existing detail without stacked modals.
 open_reading('22');q.c.call('Input.dispatchMouseEvent',{'type':'mousePressed','x':8,'y':8,'button':'left','clickCount':1});q.c.call('Input.dispatchMouseEvent',{'type':'mouseReleased','x':8,'y':8,'button':'left','clickCount':1});q.wait("document.querySelector('#questionDialog').open");q.check(q.ev("document.querySelectorAll('dialog[open]').length")==1,'Backdrop click restores a single existing detail dialog');q.close_dialog()
 for n in ['19','23','40','43','50','65','68','69','76','83','84','85','99','101','103','104','105','106','109','111','115','116','117','118','119']:
  q.question(n);q.check(q.ev("!document.querySelector('#w28OpenComparison')"),'Q'+n+' has no fictitious active comparison');q.close_dialog()
 for g in ['indigenous','riverside','quilombola','none','other']:
  q.ev('W26Data.set('+json.dumps(g)+');true');q.wait('W15App.renderedAnalyticalContext===W15.query(W26Data.ctx())');q.question('58');q.check(q.ev("document.querySelector('#w28OpenComparison').disabled&&document.querySelector('#w28DetailActions').innerText.includes('filtro foi preservado')"),g+' preserves Q16 and disables only the new unapproved combination');q.close_dialog()
 q.ev("W26Data.set('all');true");q.wait('W15App.renderedAnalyticalContext===W15.query(W26Data.ctx())');open_reading('58');q.ev("W15.set({uf:'PI',ibge:'2211001'});true");q.wait("!document.querySelector('#w28CensusComparison').open");q.check(q.ev('W28Census.state===null'),'Context change clears old comparative model and closes viewer');q.check(not[e for e in q.c.events if e.get('method')=='Runtime.exceptionThrown'],'Comparative workflows have no uncaught browser exception')
if __name__=='__main__':sys.exit(0 if main_guard(q,work)else 1)
